-- persons
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('liu-yifu', '刘义符', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '刘裕长子，刘宋第二帝，422—424年在位。即位后年少失政，徐羡之、傅亮等废黜并杀害他，改立其弟刘义隆。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘义符"}]'::jsonb, NULL, NULL, '宋少帝')
