VALUES ('feng-taihou', '冯太后', ARRAY[]::text[], NULL, NULL, 442, 1, 490, 1, ARRAY['太后','政治家'], '北魏文明太后，献文帝、孝文帝朝两度临朝，推动改革。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/冯太后"}]'::jsonb, NULL, NULL, NULL)
