VALUES ('hu-taihou', '胡太后', ARRAY[]::text[], NULL, NULL, NULL, NULL, 528, 4, ARRAY['太后','政治家'], '北魏灵太后，孝明帝生母，毒杀明帝，河阴之变后被沉河。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/胡太后"}]'::jsonb, NULL, NULL, NULL)
