-- dynasties
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, end_year, end_month, start_abs, end_abs, precision, color_token, parent_id, group_id, note)
VALUES ('wei-north', '北魏', ARRAY['魏','拓跋魏'], 'cn', 'east_asia', 386, 1, 535, 2, 4632, 6421, 'year', 'ochre', NULL, 'bei-chao', '拓跋珪386年重建代国并改称魏，439年太武帝灭北凉、统一北方。孝文帝迁都洛阳并推行制度与风俗改革；六镇之乱后政权衰弱，534年分裂为东魏、西魏，535年北魏名义终结。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, precision = EXCLUDED.precision, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, end_year, end_month, start_abs, end_abs, precision, color_token, parent_id, group_id, note)
VALUES ('song-liu', '刘宋', ARRAY['宋','南朝宋'], 'cn', 'east_asia', 420, 7, 479, 1, 5046, 5748, 'year', 'ochre', NULL, 'nan-chao', '刘裕420年取代东晋建国，都建康；文帝时期一度出现“元嘉之治”，后因宗室内乱与权臣兴起而衰弱。479年萧道成受禅，刘宋亡、南齐建立。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, precision = EXCLUDED.precision, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, end_year, end_month, start_abs, end_abs, precision, color_token, parent_id, group_id, note)
VALUES ('qi-nan', '南齐', ARRAY['齐','萧齐'], 'cn', 'east_asia', 479, 1, 502, 1, 5748, 6024, 'year', 'ochre', NULL, 'nan-chao', '萧道成479年受禅建齐，都建康；齐武帝时期政治与文化较为兴盛。此后宗室争位、皇帝更迭频繁，萧鸾一支大规模诛杀高帝和武帝后裔，最终于502年被萧衍取代。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, precision = EXCLUDED.precision, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, end_year, end_month, start_abs, end_abs, precision, color_token, parent_id, group_id, note)
VALUES ('liang-nan', '南梁', ARRAY['梁','萧梁'], 'cn', 'east_asia', 502, 1, 557, 1, 6024, 6684, 'year', 'ochre', NULL, 'nan-chao', '萧衍502年取代南齐建梁，都建康；前期推行宽政并崇佛，梁朝文化繁盛。548年侯景之乱攻陷建康、梁武帝被困而死，宗室割据内战延续至557年陈霸先受禅。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, precision = EXCLUDED.precision, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, end_year, end_month, start_abs, end_abs, precision, color_token, parent_id, group_id, note)
VALUES ('han-houjing', '汉', ARRAY['侯汉','大汉'], 'cn', 'east_asia', 552, 1, 552, 5, 6624, 6628, 'month', 'ochre', NULL, 'nan-chao', '侯景原为东魏将领，降梁后于548年发动叛乱并攻陷建康。552年初在建康称帝、国号汉，旋被陈霸先和王僧辩击败，政权仅存数月。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, precision = EXCLUDED.precision, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, end_year, end_month, start_abs, end_abs, precision, color_token, parent_id, group_id, note)
VALUES ('chen-nan', '南陈', ARRAY['陈'], 'cn', 'east_asia', 557, 1, 589, 1, 6684, 7068, 'year', 'ochre', NULL, 'nan-chao', '陈霸先557年代梁建陈，都建康；文帝、宣帝时期整顿江南并一度收复淮南。北周灭北齐后陈朝独处江南，589年隋军攻陷建康，陈亡并结束南北朝。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, precision = EXCLUDED.precision, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, end_year, end_month, start_abs, end_abs, precision, color_token, parent_id, group_id, note)
VALUES ('qi-bei', '北齐', ARRAY['齐','高齐'], 'cn', 'east_asia', 550, 1, 577, 1, 6600, 6924, 'year', 'ochre', NULL, 'bei-chao', '高洋550年取代东魏建齐，都邺；初期整军建制，后期及继位诸帝时朝政渐乱。北周武帝于577年攻灭北齐，北方归于北周。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, precision = EXCLUDED.precision, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, end_year, end_month, start_abs, end_abs, precision, color_token, parent_id, group_id, note)
VALUES ('zhou-bei', '北周', ARRAY['周','宇文周'], 'cn', 'east_asia', 557, 2, 581, 3, 6685, 6974, 'month', 'ochre', NULL, 'bei-chao', '宇文觉557年受禅建周，都长安，实际政权先受宇文护控制。武帝亲政后整军并于577年灭北齐、统一北方；581年杨坚受禅建隋，北周结束。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, precision = EXCLUDED.precision, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, end_year, end_month, start_abs, end_abs, precision, color_token, parent_id, group_id, note)
VALUES ('wei-east', '东魏', ARRAY['魏'], 'cn', 'east_asia', 534, 11, 550, 2, 6418, 6601, 'year', 'ochre', NULL, 'bei-chao', '高欢控制洛阳朝廷后，于534年迁元善见至邺，东魏由此建立。皇帝长期受高氏挟制，550年高欢之子高洋受禅建北齐，东魏亡。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, precision = EXCLUDED.precision, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, end_year, end_month, start_abs, end_abs, precision, color_token, parent_id, group_id, note)
VALUES ('wei-west', '西魏', ARRAY['魏'], 'cn', 'east_asia', 535, 2, 557, 2, 6421, 6685, 'year', 'ochre', NULL, 'bei-chao', '宇文泰于535年在长安拥立元宝炬，建立西魏，与高欢控制的东魏对峙。西魏朝廷由宇文泰掌握，557年宇文觉受禅建北周，西魏结束。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, precision = EXCLUDED.precision, group_id = EXCLUDED.group_id, note = EXCLUDED.note;

